// Screens of the app. They only read the shared state; app.js handles every action.
import { AGES, AVATARS, BANK, CATEGORIES, CARD_DIFFICULTIES, DIFFICULTIES, FORMATS, MODES, PACKS, packConfig, selectCards } from '../content.js';
import { validateConfig } from '../game.js';
import { S } from './state.js';
import { ACCESSORIES, COLORS, COLOR_NAMES, button, escape, quantity, seconds, title } from './util.js';
import { icon, mascot, pineapple } from './icons.js';
import { loadGame, loadPresets, loadSeen } from './store.js';
import { loadSession, inviteUrl } from './platform.js';
import { gameStats } from './stats.js';
import { qrSvg } from './qr.js';
import { pen } from './canvas.js';

export const STEPS = ['Piñas', 'Modalidades', 'Categorías', 'Reglas', '¡Todo listo!'];
export const categories = () => [...CATEGORIES, ...S.customCategories];
export function categoryName(id) { return categories().find(c => c.id === id)?.name || S.config.categoryLabels?.[id] || S.game?.state.config.categoryLabels?.[id] || 'Personalizada'; }
export const isActive = () => !S.remote || S.remote.snapshot?.identity.teamId === S.game?.team.id;
export const isHost = () => !S.remote || !!S.remote.snapshot?.identity.host;
export const isViewer = () => !!S.remote?.snapshot?.identity.viewer;
export const canControl = () => isActive() && (!S.remote || S.connected);
export function choice(action, value, label, selected, detail = '') { return `<button class="choice ${selected ? 'selected' : ''}" data-action="${action}" data-value="${value}" aria-pressed="${selected}"><span>${label}</span>${detail ? `<small>${detail}</small>` : ''}${selected ? icon('check') : ''}</button>`; }
// How many games a selection allows without repeating cards: a typical game uses about 90.
export function selectionInfo(config, teams) {
  const cards = selectCards(config, S.customCards);
  const seen = new Set(loadSeen());
  const fresh = cards.filter(card => !seen.has(card.id)).length;
  const perGame = config.format === 'rounds3' ? (config.pileSize || 40) : Math.max(12, Math.round(teams.length * config.rounds * Math.max(3, config.duration / 10)));
  return { cards, fresh, games: Math.floor(fresh / perGame), perGame };
}

// ---- Shell ----
export function header() {
  const badge = S.remote ? `<span class="room-badge ${S.connected ? '' : 'disconnected'}">${icon(isViewer() ? 'screen' : 'wifi')} ${isViewer() ? 'Marcador' : 'Sala'} ${S.remote.code}</span>` : '<span class="header-tagline">Juntos es más divertido</span>';
  return `<header class="site-header"><button class="brand" data-action="home" aria-label="AdiPiña, inicio"><img src="./icon.svg" alt=""/><span>Adi<span class="brand-pina">Piña</span><span class="brand-dot">.</span></span></button><div class="header-right">${badge}<button class="icon-btn" data-action="sound" aria-label="${S.settings.muted ? 'Activar' : 'Silenciar'} sonido" aria-pressed="${S.settings.muted}">${icon(S.settings.muted ? 'mute' : 'volume')}</button><button class="icon-btn" data-action="settings" aria-label="Ajustes">${icon('gear')}</button><button class="help-btn" data-action="help" aria-label="Cómo se juega">${icon('info')}<span>Cómo se juega</span></button></div></header>`;
}
export function footer() { return `<footer class="site-footer"><span>${icon('leaf')} Hecho para hacer piña.</span><span>En persona · Sin cuentas · Con muchas risas</span><span class="footer-version">AdiPiña / 1.0</span></footer>`; }
export function main() {
  mascot.index = 0;
  const views = { home: homeView, quick: quickView, setup: setupView, join: joinView, lobby: lobbyView, game: gameView };
  return (views[S.screen] || gameView)();
}

// ---- Home and quick game ----
export function homeView() {
  const resumable = loadGame();
  const roomSession = loadSession();
  return `<section class="hero hero-redesign"><div class="hero-copy"><h1>Adivina.<br>Ríete.<br><span class="coral-word">Haz piña.<svg viewBox="0 0 400 20" aria-hidden="true"><path d="M4 14Q160-6 395 8"/></svg></span></h1><p>Un juego por equipos para convertir cualquier quedada en un buen plan.</p></div>
    <div class="hero-art"><img src="./ui/mascotas.webp" width="640" height="640" alt="Dos piñas simpáticas preparadas para jugar" fetchpriority="high"/></div>
    <div class="hero-actions">${button('new-local', `¡A jugar! ${icon('arrow')}`)}${button('new-room', `${icon('people')} Crear sala`, 'secondary')}${button('join-page', `${icon('key')} Unirme con código`, 'secondary')}</div>
    <div class="hero-details"><div class="hero-note"><span>Un móvil o uno por piña</span><button class="text-link" data-action="help">Cómo se juega</button></div><div class="hero-meta"><span>${icon('people')} 2–12 piñas</span><span>${icon('timer')} ${quantity(BANK.length, 'tarjeta', 'tarjetas')}</span></div>
    ${resumable && resumable.state.phase !== 'finished' ? `<div class="resume-banner">Hay una partida guardada. ${button('restore-local', 'Continuar', 'text')}</div>` : ''}${roomSession ? `<div class="resume-banner">Tu última sala: ${escape(roomSession.code)} ${button('restore-room', 'Volver a la sala', 'text')}</div>` : ''}</div></section>
    <section class="ways-section"><div class="section-heading"><h2>Tres maneras de liarla.</h2><p>Elige una, mezcla dos o juega con las tres. Y si os animáis: una palabra, palabras prohibidas o tararear.</p></div><div class="mode-preview-grid">${['drawing', 'mime', 'description'].map((id, i) => { const m = MODES[id]; return `<article class="mode-preview ${m.color}"><div class="mode-preview-top"><span class="mode-icon">${icon(m.icon)}</span><span class="card-number">0${i + 1}</span></div><h3>${m.verb}<span aria-hidden="true">↗</span></h3><p>${id === 'drawing' ? 'Que tu obra de arte hable por ti. En papel o en la pantalla.' : id === 'mime' ? 'Saca tu lado dramático. Ni una palabra, solo gestos.' : 'Esa palabra la sabes. Ahora cuéntala sin decirla.'}</p><span class="mode-label">${m.name}</span></article>`; }).join('')}</div></section>
    <section class="how-strip"><span class="how-title">El plan, en tres pasos</span><div><b>1</b><span>Forma tu piña</span></div><span class="strip-arrow" aria-hidden="true">→</span><div><b>2</b><span>Elige cómo jugar</span></div><span class="strip-arrow" aria-hidden="true">→</span><div><b>3</b><span>¡Que empiecen las pistas!</span></div></section>`;
}
export function quickView() {
  const q = S.quick, config = packConfig(S.config, q.pack);
  const presets = loadPresets();
  return `<section class="setup-shell quick-shell"><div class="setup-top"><button class="text-link" data-action="home">${icon('back')} Inicio</button><span class="small-tag">${icon(S.playType === 'room' ? 'wifi' : 'phone')} ${S.playType === 'room' ? 'Un móvil por piña' : 'Un móvil compartido'}</span></div>
    ${title('PARTIDA RÁPIDA', '¿A qué jugamos?', 'Elige un pack y cuántas piñas sois. Las reglas vienen puestas; podéis cambiarlas cuando queráis.')}
    <div class="segmented">${choice('play-type', 'local', `${icon('phone')} Un móvil`, S.playType === 'local')}${choice('play-type', 'room', `${icon('wifi')} Un móvil por piña`, S.playType === 'room')}</div>
    <div class="category-grid pack-grid">${PACKS.map((pack, i) => { const count = selectCards(packConfig(S.config, pack.id), S.customCards).length; return `<button data-action="quick-pack" data-value="${pack.id}" class="category pack-tile ${['mint', 'paper', 'peach', 'lavender'][i % 4]} ${q.pack === pack.id ? 'selected' : ''}" aria-pressed="${q.pack === pack.id}">${icon(pack.icon)}<span>${escape(pack.name)}<small>${escape(pack.description)}</small><small class="pack-count">${count} tarjetas</small></span><span class="category-check" aria-hidden="true">${q.pack === pack.id ? icon('check') : '+'}</span></button>`; }).join('')}</div>
    <div class="inline-field quick-team-count panel"><div><label for="quick-teams">Número de piñas</label><p class="hint">Una pareja o equipo por piña.</p></div><div class="step-control">${button('quick-less', '−', 'icon-btn', `${q.teams <= 2 ? 'disabled' : ''} aria-label="Quitar una piña"`)}<output id="quick-teams">${q.teams}</output>${button('quick-more', '+', 'icon-btn', `${q.teams >= 12 ? 'disabled' : ''} aria-label="Añadir una piña"`)}</div></div>
    <div class="panel"><label for="quick-players">¿Quiénes jugáis? <span>Opcional · una persona por línea · se reparten al azar</span></label><textarea id="quick-players" rows="3" placeholder="Por ejemplo:&#10;Ana&#10;Sergio&#10;Lucía" data-input="quick-players">${escape(q.players)}</textarea></div>
    <p class="hint">${FORMATS[config.format].name} · ${config.modes.map(id => MODES[id].name).join(', ')} · ${config.duration} s por turno · ${config.format === 'rounds3' ? 'tres rondas' : quantity(config.rounds, 'ronda', 'rondas')}.</p>
    ${presets.length ? `<div class="field-group"><h2>Vuestras partidas favoritas</h2><div class="choices-row">${presets.map((preset, i) => choice('use-preset', i, escape(preset.name), false, `${preset.teams?.length || 2} piñas`)).join('')}</div></div>` : ''}
    <div class="lobby-actions">${button('quick-start', `${S.playType === 'room' ? 'Abrir sala' : 'Empezar partida'} ${icon('arrow')}`, 'primary large')}${button('quick-customize', 'Personalizar todas las reglas', 'text')}</div></section>`;
}

// ---- Full setup (five steps) ----
export function setupView() {
  return `<section class="setup-shell"><div class="setup-top"><button class="text-link" data-action="home">${icon('back')} Inicio</button><span class="small-tag">${icon(S.playType === 'room' ? 'wifi' : 'phone')} ${S.playType === 'room' ? 'Un móvil por piña' : 'Un móvil compartido'}</span></div><nav class="stepper" aria-label="Configuración">${STEPS.map((label, i) => `<button data-action="step" data-value="${i}" class="step ${i === S.step ? 'active' : ''} ${i < S.step ? 'complete' : ''}" ${i === S.step ? 'aria-current="step"' : ''}><span>${i < S.step ? icon('check') : i + 1}</span><strong>${label}</strong></button>`).join('')}</nav>
    <div class="setup-content">${[teamView, modesView, contentView, rulesView, reviewView][S.step]()}</div><div class="setup-nav">${button(S.step ? 'previous-step' : 'home', `${icon('back')} ${S.step ? 'Atrás' : 'Inicio'}`, 'secondary')}<span>Paso ${S.step + 1} de 5</span>${button(S.step === 4 ? 'begin' : 'next-step', `${S.step === 4 ? (S.playType === 'room' ? 'Abrir sala' : 'Empezar partida') : 'Continuar'} ${icon('arrow')}`)}</div></section>`;
}
function teamView() {
  const { teams } = S;
  return `${title('LA BUENA COMPAÑÍA', 'Forma tu piña', S.playType === 'room' ? 'Prepara los equipos. Después, cada piña se une a la sala desde su móvil.' : 'Al menos dos equipos. Elegid nombre, color y un poquito de actitud.')}
    <div class="segmented">${choice('team-type', 'manual', `${icon('people')} Equipos manuales`, S.teamType === 'manual')}${choice('team-type', 'random', `${icon('shuffle')} Equipos aleatorios`, S.teamType === 'random')}</div>
    ${S.teamType === 'manual' ? `<div class="inline-field"><label for="team-count">Número de piñas</label><div class="step-control">${button('team-less', '−', 'icon-btn', `${teams.length <= 2 ? 'disabled' : ''} aria-label="Quitar una piña"`)}<output id="team-count">${teams.length}</output>${button('team-more', '+', 'icon-btn', `${teams.length >= 12 ? 'disabled' : ''} aria-label="Añadir una piña"`)}</div></div>` : `<div class="panel random-panel"><label for="players">¿Quiénes jugáis? <span>Una persona por línea</span></label><textarea id="players" rows="5" placeholder="Por ejemplo:&#10;Ana&#10;Sergio&#10;Lucía" data-input="players">${escape(S.randomPlayers)}</textarea>${savedPlayersChips()}<div class="random-controls"><label>Repartir por<select data-input="random-method"><option value="count" ${S.randomMethod === 'count' ? 'selected' : ''}>Número de equipos</option><option value="size" ${S.randomMethod === 'size' ? 'selected' : ''}>Personas por equipo</option></select></label><label>${S.randomMethod === 'count' ? 'Piñas' : 'Personas por piña'}<input type="number" min="2" max="${S.randomMethod === 'count' ? '12' : '100'}" value="${S.randomMethod === 'count' ? S.randomCount : S.randomSize}" data-input="random-value"/></label>${button('shuffle', `${icon('shuffle')} Sortear equipos`, 'primary')}</div><p class="hint">Si sobran personas, se reparten entre los equipos. Nadie se queda fuera.</p></div>`}
    ${S.teamType === 'random' && teams.some(t => t.members.length) ? `<p class="notice">${icon('people')} El reparto: ${teams.map(t => `${escape(t.name)} (${t.members.length})`).join(' · ')}. Podéis cambiar de equipo antes de continuar.</p>` : ''}
    <div class="team-grid">${teams.map((team, i) => teamCard(team, i)).join('')}</div>`;
}
function savedPlayersChips() {
  const saved = S.savedPlayers || [];
  if (!saved.length) return '';
  const current = new Set(S.randomPlayers.split('\n').map(v => v.trim()).filter(Boolean));
  return `<span class="field-label">Jugadores de otras partidas · toca para añadir</span><div class="accessories">${saved.slice(-24).map(name => `<button class="chip ${current.has(name) ? 'selected' : ''}" data-action="add-player" data-value="${escape(name)}" aria-pressed="${current.has(name)}">${escape(name)}</button>`).join('')}</div>`;
}
function teamCard(team, i) {
  return `<article class="team-editor panel"><div class="team-editor-top"><span class="eyebrow">PIÑA ${String(i + 1).padStart(2, '0')}</span><span class="mini-label">A vuestra manera</span></div><div class="team-customize"><div class="team-avatar">${pineapple(team)}</div><div class="team-options"><label for="team-name-${i}">Nombre del equipo</label><input id="team-name-${i}" maxlength="40" value="${escape(team.name)}" data-team="${i}" data-field="name"/><span class="field-label" id="avatar-label-${i}">Personaje</span>${avatarPicker(team, i)}<span class="field-label">${team.avatar ? 'Color del equipo' : 'Color de la piña'}</span><div class="swatches">${COLORS.map((color, c) => `<button class="swatch ${team.color === color ? 'selected' : ''}" style="--swatch:${color}" data-action="color" data-team="${i}" data-value="${color}" aria-label="Piña ${COLOR_NAMES[c].toLowerCase()} del equipo ${i + 1}" aria-pressed="${team.color === color}">${team.color === color ? icon('check') : ''}</button>`).join('')}</div>${team.avatar ? '' : `<span class="field-label">Accesorios · puedes combinar</span><div class="accessories">${Object.entries(ACCESSORIES).map(([id, name]) => `<button data-action="accessory" data-team="${i}" data-value="${id}" aria-pressed="${team.accessories.includes(id)}" class="chip ${team.accessories.includes(id) ? 'selected' : ''}">${name}</button>`).join('')}</div>`}<label for="team-level-${i}">Nivel de las tarjetas <span>Para equilibrar peques y mayores</span></label><select id="team-level-${i}" data-team-level="${i}"><option value="">Como el resto de la partida</option>${Object.entries(CARD_DIFFICULTIES).map(([id, name]) => `<option value="${id}" ${team.difficulty === id ? 'selected' : ''}>${name}</option>`).join('')}</select></div></div>
    ${S.teamType === 'random' ? `<div class="member-list">${team.members.map((member, j) => `<label><span>${escape(member)}</span><select aria-label="Equipo de ${escape(member)}" data-move-team="${i}" data-member="${j}">${S.teams.map((t, k) => `<option value="${k}" ${i === k ? 'selected' : ''}>${escape(t.name)}</option>`).join('')}</select></label>`).join('') || '<span class="hint">Aún sin integrantes. Usa el sorteo.</span>'}</div>` : `<label for="members-${i}">Integrantes <span>Opcional · una persona por línea</span></label><textarea id="members-${i}" rows="2" placeholder="¿Quién da las pistas?" data-team="${i}" data-field="members">${escape(team.members.join('\n'))}</textarea>`}</article>`;
}
// Five illustrated characters plus the classic pineapple, which keeps free colour and accessory customisation.
function avatarPicker(team, i) {
  const option = (id, label, art) => { const selected = (team.avatar || '') === id; return `<button class="avatar-option ${selected ? 'selected' : ''}" data-action="avatar" data-team="${i}" data-value="${id}" aria-pressed="${selected}">${art}<span>${label}</span>${selected ? icon('check') : ''}</button>`; };
  return `<div class="avatar-picker" role="group" aria-labelledby="avatar-label-${i}">${AVATARS.map(avatar => option(avatar.id, avatar.name, pineapple({ avatar: avatar.id }, '', true))).join('')}${option('', 'Tu propia piña', pineapple({ color: team.color, accessories: team.accessories }))}</div>`;
}
function modesView() {
  const { config } = S;
  const threeRounds = config.format === 'rounds3';
  return `${title('UN POCO DE TALENTO. O NO.', '¿Cómo vais a adivinar?', 'Elegid el formato y las modalidades. En el modo por rondas, el orden de selección es el orden de las rondas.')}
    <div class="field-group"><h2>Formato</h2><div class="choices-row">${Object.entries(FORMATS).map(([id, format]) => choice('format', id, format.name, config.format === id, format.description)).join('')}</div></div>
    ${threeRounds ? `<div class="panel"><h2>${icon('shuffle')} Tres rondas con las mismas tarjetas</h2><p>Ronda 1: descripción libre. Ronda 2: una sola palabra. Ronda 3: mímica. Cada ronda termina cuando se adivinan todas las tarjetas del montón; los saltos vuelven debajo del montón.</p><label for="pile-size">Tarjetas en el montón <span>5–200 · unas ${Math.max(10, S.teams.length * 8)} para ${quantity(S.teams.length, 'piña', 'piñas')}</span></label><input id="pile-size" type="number" min="5" max="200" value="${config.pileSize}" data-config="pileSize"/></div>` : `
    <div class="mode-select-grid">${Object.entries(MODES).map(([id, m]) => `<button class="mode-select ${m.color} ${config.modes.includes(id) ? 'selected' : ''}" data-action="mode" data-value="${id}" aria-pressed="${config.modes.includes(id)}"><span class="select-check">${config.modes.includes(id) ? config.modes.indexOf(id) + 1 : '+'}</span><span class="mode-icon">${icon(m.icon)}</span><h2>${m.name}</h2><p>${m.rule}${id === 'taboo' ? ' Solo tarjetas con palabras prohibidas.' : id === 'hum' ? ' Solo canciones.' : ''}</p></button>`).join('')}</div>
    ${config.modes.length > 1 ? `<div class="field-group"><h2>¿Mezclamos o vamos por rondas?</h2><div class="choices-row">${choice('mode-style', 'mixed', 'Modo mezclado', config.modeStyle === 'mixed', 'Cada tarjeta tiene una modalidad que le encaja.')}${choice('mode-style', 'rounds', 'Modo por rondas', config.modeStyle === 'rounds', 'Una modalidad por ronda, en el orden elegido.')}</div>${config.modeStyle === 'rounds' ? `<p class="hint">${config.modes.map(id => MODES[id].name).join(' → ')} → repetir. Una ronda termina cuando todas las piñas han jugado.</p>` : ''}</div>` : ''}
    ${config.modes.includes('drawing') ? `<div class="field-group"><h2>Para los dibujos…</h2><div class="choices-row">${choice('drawing-option', 'paper', `${icon('pencil')} En papel`, config.drawing === 'paper', 'Preparad papel y algo para dibujar.')}${choice('drawing-option', 'screen', `${icon('phone')} En la pantalla`, config.drawing === 'screen', 'Lienzo con colores, goma y deshacer.')}</div></div>` : ''}`}`;
}
function contentView() {
  const { config } = S;
  const info = selectionInfo(config, S.teams);
  const musicSubs = CATEGORIES.find(c => c.id === 'music').subcategories;
  return `${title('¿DE QUÉ SABE VUESTRA PIÑA?', 'Elegid los ingredientes', 'Un pack listo para jugar o vuestra propia mezcla de temas.')}
    <div class="field-group"><h2>Packs</h2><div class="choices-row">${PACKS.map(pack => choice('pack', pack.id, `${icon(pack.icon)} ${escape(pack.name)}`, config.pack === pack.id, escape(pack.description))).join('')}</div></div>
    <div class="content-toolbar"><span class="count-badge">${info.cards.length} respuestas disponibles</span><div>${button('all-categories', 'Todas', 'text')}${button('no-categories', 'Ninguna', 'text')}</div></div>
    ${info.cards.length && info.games < 2 ? `<p class="notice" role="status">${icon('info')} Con esta selección quedan ${info.fresh} tarjetas sin ver: ${info.games ? 'da para una partida' : 'puede que no llegue para una partida completa'} sin repetir. Añadid temas o cambiad la dificultad.</p>` : info.cards.length ? `<p class="hint">Da para unas ${info.games} partidas sin repetir tarjetas.</p>` : ''}
    <div class="category-grid">${categories().map(c => `<button data-action="category" data-value="${escape(c.id)}" class="category ${config.categories.includes(c.id) ? 'selected' : ''}" aria-pressed="${config.categories.includes(c.id)}">${icon(c.icon || 'star')}<span>${escape(c.name)}${S.customCategories.includes(c) ? '<small>Tu categoría</small>' : ''}</span><span class="category-check">${config.categories.includes(c.id) ? icon('check') : '+'}</span></button>`).join('')}</div>
    ${config.categories.includes('music') ? `<div class="subcategories"><span>Dentro de Música</span>${musicSubs.map(sub => `<button class="chip ${(config.subcategories.music || []).includes(sub) ? 'selected' : ''}" aria-pressed="${(config.subcategories.music || []).includes(sub)}" data-action="music-sub" data-value="${sub}">${sub}</button>`).join('')}</div>` : ''}
    <div class="field-group"><h2>Dificultad</h2><div class="segmented difficulty">${Object.entries(DIFFICULTIES).map(([id, name]) => choice('difficulty', id, name, config.difficulty === id)).join('')}</div></div>
    <div class="field-group"><h2>¿Quién juega?</h2><div class="choices-row">${Object.entries(AGES).map(([id, name]) => choice('ages', id, name, (config.ages || 'any') === id, id === 'kids' ? 'Solo tarjetas pensadas para peques.' : id === 'family' ? 'Sin referencias para mayores.' : 'Todas las tarjetas.')).join('')}</div>${choice('mode-fit', 'toggle', 'Solo tarjetas que encajan con vuestras modalidades', !!config.modeFit, 'Por ejemplo, para mímica: cosas que se actúan bien.')}</div>
    <div class="custom-banner"><span class="custom-icon">${icon('plus')}</span><div><h3>Vuestras historias también juegan.</h3><p>Crea categorías y añade respuestas, una por línea. También podéis importarlas de otro móvil.</p></div>${button('custom-editor', 'Añadir contenido', 'secondary')}</div>
    <div class="field-group"><h2>¿Qué contenido usamos?</h2><div class="choices-row">${choice('source', 'combined', 'Banco + vuestras respuestas', config.source === 'combined', `${BANK.length} tarjetas incluidas y ${S.customCards.length} propias.`)}${choice('source', 'custom', 'Solo vuestras respuestas', config.source === 'custom', `${S.customCards.length} tarjetas propias guardadas en este móvil.`)}</div></div>${S.customCards.length || S.customCategories.length ? `<button class="text-link" data-action="manage-custom">Gestionar mis respuestas y categorías ${icon('arrow')}</button>` : ''}`;
}
function rulesView() {
  const { config, teams } = S;
  const byPoints = config.target != null;
  return `${title('VUESTRA PARTIDA, VUESTRAS REGLAS', 'Un último toque', 'Cada acierto suma un punto. Tú confirmas las respuestas y el juego lleva la cuenta.')}
    <div class="rules-grid"><div class="panel"><h2>${icon('timer')} Tiempo por turno</h2><div class="segmented">${[30, 60, 90].map(n => choice('duration', n, `${n} s`, config.duration === n)).join('')}</div><label for="custom-time">O elige tu tiempo <span>10–600 segundos</span></label><input id="custom-time" type="number" min="10" max="600" value="${config.duration}" data-config="duration"/>${config.modes.includes('drawing') && config.format !== 'rounds3' ? `<label for="drawing-bonus">Tiempo extra en turnos de dibujo <span>0–120 s · por rondas o solo dibujo</span></label><input id="drawing-bonus" type="number" min="0" max="120" step="5" value="${config.drawingBonus || 0}" data-config="drawingBonus"/>` : ''}</div>
    <div class="panel"><h2>${icon('shuffle')} ¿Cuándo termina?</h2>${config.format === 'rounds3' ? '<p class="hint">En «Tres rondas» la partida termina cuando se adivinan todas las tarjetas de la tercera ronda.</p>' : `<div class="choices-stack">${choice('goal', 'rounds', 'Por rondas', !byPoints, 'Una ronda = un turno para cada piña.')}${choice('goal', 'points', 'Por puntos', byPoints, 'Gana quien llegue antes al objetivo (se completa la ronda).')}</div>${byPoints ? `<label for="target">Puntos para ganar <span>3–500</span></label><input id="target" type="number" min="3" max="500" value="${config.target}" data-config="target"/>` : `<label for="rounds">Número de rondas <span>1–20</span></label><input id="rounds" type="number" min="1" max="20" value="${config.rounds}" data-config="rounds"/><p class="hint">Aproximadamente ${Math.round(config.duration * config.rounds * teams.length / 60)} minutos de juego, más los cambios de turno.</p>`}`}</div>
    <div class="panel"><h2>${icon('skip')} Saltos por turno</h2><label for="skip-policy">Si una respuesta se resiste…</label><select id="skip-policy" data-config="skipPolicy"><option value="unlimited" ${config.skipPolicy === 'unlimited' ? 'selected' : ''}>Saltos ilimitados</option><option value="limited" ${config.skipPolicy === 'limited' ? 'selected' : ''}>Limitar los saltos</option><option value="off" ${config.skipPolicy === 'off' ? 'selected' : ''}>Sin saltos</option></select>${config.skipPolicy === 'limited' ? `<label for="skip-limit">Máximo por turno</label><input id="skip-limit" type="number" min="1" max="99" value="${config.skipLimit}" data-config="skipLimit"/>` : ''}</div>
    <div class="panel"><h2>${icon('star')} Puntos al saltar</h2><div class="choices-stack">${choice('penalty', 'false', 'Sin penalización', !config.penalty, 'Saltar no cambia la puntuación.')}${choice('penalty', 'true', 'Restar un punto', config.penalty, 'Las puntuaciones pueden ser negativas.')}</div>${config.skipPolicy === 'off' ? '<p class="hint">No se aplicará mientras los saltos estén desactivados.</p>' : ''}</div>
    ${config.format === 'rounds3' ? '' : `<div class="panel"><h2>${icon('magic')} Extras</h2><div class="choices-stack">${choice('toggle-rule', 'allPlay', '¡Todos juegan!', !!config.allPlay, 'De vez en cuando, una tarjeta la puede acertar cualquier piña.')}${choice('toggle-rule', 'steal', 'Robo de tarjeta', !!config.steal, 'Si la piña no la saca, otra puede robar el punto.')}${choice('toggle-rule', 'lightning', 'Ronda relámpago', !!config.lightning && !byPoints, 'Última ronda de 30 segundos con puntos dobles.')}</div></div>`}</div>
    <div class="notice">${icon('lock')} Las respuestas se ocultan al pausar y al pasar el móvil. Una tarjeta mostrada no se repite, aunque no llegue a acertarse.</div>`;
}
function reviewView() {
  const { config, teams } = S;
  const cards = selectCards(config, S.customCards);
  const errors = validateConfig(config, teams, cards);
  const extras = [config.allPlay && 'Todos juegan', config.steal && 'Robo', config.lightning && config.target == null && 'Ronda relámpago'].filter(Boolean);
  return `${title('TODO PREPARADO', '¿Hacemos piña?', S.playType === 'room' ? 'Abre la sala, comparte el código y espera a que se una un móvil por equipo.' : 'Reúne a las piñas. La primera respuesta se revela cuando quien da pistas esté listo.')}
    ${errors.length ? `<div class="error-box" role="alert">${errors.map(error => `<p>${escape(error)}</p>`).join('')}</div>` : ''}
    <div class="review-teams">${teams.map(team => `<article>${pineapple(team)}<h3>${escape(team.name)}</h3><p>${team.members.length ? team.members.map(escape).join(', ') : 'Elegid quién da las pistas'}${team.difficulty ? ` · ${CARD_DIFFICULTIES[team.difficulty]}` : ''}</p></article>`).join('')}</div>
    <div class="review-details panel"><div><span>Modalidades</span><strong>${config.format === 'rounds3' ? 'Descripción · Una palabra · Mímica' : config.modes.map(id => MODES[id].name).join(' · ') || 'Sin seleccionar'}</strong><small>${config.format === 'rounds3' ? `Tres rondas con ${config.pileSize} tarjetas` : config.modes.length > 1 ? config.modeStyle === 'rounds' ? 'Por rondas, en este orden' : 'Mezcladas en cada tarjeta' : 'Una modalidad'}</small></div><div><span>Tiempo y final</span><strong>${config.duration} segundos · ${config.format === 'rounds3' ? 'tres rondas' : config.target != null ? `hasta ${config.target} puntos` : quantity(config.rounds, 'ronda', 'rondas')}</strong><small>${config.format === 'rounds3' || config.target != null ? 'Termina al completar la ronda' : `${teams.length * config.rounds} turnos en total`}${extras.length ? ` · ${extras.join(', ')}` : ''}</small></div><div><span>Contenido</span><strong>${cards.length} respuestas · ${DIFFICULTIES[config.difficulty]}</strong><small>${config.pack ? `Pack ${escape(PACKS.find(p => p.id === config.pack)?.name || '')}` : config.categories.map(categoryName).map(escape).join(', ') || 'Sin categorías'}</small></div><div><span>Saltos y puntos</span><strong>${config.skipPolicy === 'off' ? 'Sin saltos' : config.skipPolicy === 'limited' ? `${config.skipLimit} saltos por turno` : 'Saltos ilimitados'}</strong><small>Acierto +1${config.skipPolicy !== 'off' ? config.penalty ? ' · Salto −1' : ' · Salto sin penalización' : ''}</small></div></div>
    ${config.modes.includes('drawing') && config.format !== 'rounds3' ? `<p class="notice">${icon('pencil')} ${config.drawing === 'paper' ? 'Preparad papel y lápiz para los turnos de dibujo.' : 'En dibujo, lee en privado y abre el lienzo antes de enseñar la pantalla.'}</p>` : ''}
    <div class="centered">${button('save-preset', `${icon('star')} Guardar como favorita`, 'text')}</div>`;
}

// ---- Rooms ----
export function joinView() {
  return `<section class="narrow-shell">${title('CADA PIÑA CON SU MÓVIL', 'Únete a la partida', 'Pide el código a quien haya creado la sala. Solo necesitáis un móvil por pareja o equipo.')}
    <div class="panel join-panel"><label for="room-code">Código de sala</label><input id="room-code" class="code-input" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" placeholder="000000" value="${S.joinLobby?.code || new URLSearchParams(location.search).get('sala')?.replace(/\D/g, '').slice(0, 6) || S.lastRoomCode}"/>${button('find-room', `Buscar sala ${icon('arrow')}`)}<p class="hint">Usad la misma dirección de AdiPiña en todos los móviles, o escanead el QR de la sala.</p></div>
    <div class="panel join-panel"><label for="recovery-key">¿Cambiáis de móvil? <span>Código de recuperación o clave del maestro</span></label><input id="recovery-key" autocomplete="off" autocapitalize="characters" spellcheck="false" maxlength="16" placeholder="ABC-DEF"/>${button('recover-room', `Recuperar acceso ${icon('arrow')}`, 'secondary')}<p class="hint">El maestro genera el código en «Gestionar sala». Sirve una sola vez y caduca en pocos minutos; el móvil anterior deja de funcionar.</p></div>
    ${S.joinLobby ? `<div class="field-group"><h2>Sala ${S.joinLobby.code}: elegid vuestra piña</h2><div class="join-team-grid">${S.joinLobby.teams.map(team => `<button class="join-team ${S.joinTeamId === team.id ? 'selected' : ''}" data-action="join-select" data-value="${escape(team.id)}" aria-pressed="${S.joinTeamId === team.id}" ${team.claimed ? 'disabled' : ''}>${pineapple(team)}<strong>${escape(team.name)}</strong><small>${team.claimed ? 'Ya tiene móvil' : 'Disponible'}</small></button>`).join('')}</div>${S.joinDetails ? `<div class="panel"><label for="join-name">Nombre de vuestra piña</label><input id="join-name" maxlength="40" value="${escape(S.joinDetails.name)}"/><label for="join-members">Integrantes <span>Una persona por línea</span></label><textarea id="join-members" rows="3" placeholder="Ana&#10;Sergio">${escape(S.joinDetails.members.join('\n'))}</textarea><label for="join-avatar">Personaje</label><select id="join-avatar"><option value="">Tu propia piña</option>${AVATARS.map(avatar => `<option value="${avatar.id}" ${S.joinDetails.avatar === avatar.id ? 'selected' : ''}>${avatar.name}</option>`).join('')}</select><label for="join-color">Color</label><select id="join-color">${COLORS.map((color, i) => `<option value="${color}" ${S.joinDetails.color === color ? 'selected' : ''}>${COLOR_NAMES[i]}</option>`).join('')}</select><span class="field-label">Accesorios</span><div class="accessories">${Object.entries(ACCESSORIES).map(([id, label]) => `<label class="check-chip"><input type="checkbox" name="join-accessory" value="${id}" ${S.joinDetails.accessories.includes(id) ? 'checked' : ''}/>${label}</label>`).join('')}</div>${button('join-room', `¡Somos esta piña! ${icon('check')}`, 'primary full-width')}</div>` : ''}</div>` : ''}${button('home', `${icon('back')} Inicio`, 'text')}</section>`;
}
const onlinePill = team => team.claimed ? `<span class="status-pill ${team.online ? 'ready' : ''}">${team.online ? `${icon('wifi')} Conectado` : 'Sin conexión ahora'}</span>` : '';
export function lobbyView() {
  if (isViewer()) return `<section class="finished-shell"><span class="eyebrow">MARCADOR · SALA ${S.remote.code}</span>${pineapple({ color: COLORS[0], accessories: ['glasses'] }, 'handoff-fruit')}<h1>El marcador está listo</h1><p>Aparecerán aquí los turnos, el tiempo y los puntos en cuanto empiece la partida. Nunca se muestran las respuestas.</p></section>`;
  const data = S.remote.snapshot;
  const claimed = data.teams.filter(team => team.claimed).length;
  const myTeam = data.teams.find(team => team.id === data.identity.teamId);
  const invite = inviteUrl(S.settings, S.remote.code);
  return `<section class="setup-shell">${title('EL PUNTO DE ENCUENTRO', 'Ya estáis en la sala', data.identity.host ? 'Comparte el código o el QR. Cada piña elige su equipo desde un móvil y se une.' : 'Vuestra piña está dentro. El maestro empezará cuando todos estéis preparados.')}
    <div class="room-code-panel"><span>CÓDIGO DE SALA</span><strong>${S.remote.code}</strong>${data.identity.host ? qrSvg(invite, `Código QR para unirse a la sala ${S.remote.code}`) : ''}${button('copy-room', `${icon('copy')} Copiar invitación`, 'secondary')}<small>${S.connected ? 'Conectados' : 'Reconectando…'} · ${claimed} de ${data.teams.length} móviles preparados</small></div>
    ${myTeam ? `<div class="notice">${icon('check')} Este móvil juega con <strong>${escape(myTeam.name)}</strong>.</div>` : data.identity.host ? `<div class="notice">${icon('phone')} Puedes usar este móvil solo como maestro, o elegir debajo vuestra piña para jugar también.</div>` : ''}
    <div class="lobby-team-grid">${data.teams.map(team => `<article class="panel lobby-team">${pineapple(team)}<h3>${escape(team.name)}</h3><p>${team.members.map(escape).join(', ') || 'Sin integrantes indicados'}</p><span class="status-pill ${team.claimed ? 'ready' : ''}">${team.claimed ? `${icon('check')} Móvil listo` : 'Esperando móvil'}</span>${data.identity.host ? onlinePill(team) : ''}${data.identity.host ? team.claimed ? button('release-team', 'Liberar móvil', 'text', `data-value="${escape(team.id)}"`) : !myTeam ? button('host-claim', 'Jugar con esta piña', 'secondary', `data-value="${escape(team.id)}"`) : '' : ''}</article>`).join('')}</div>
    <p class="hint centered">${data.config.format === 'rounds3' ? 'Tres rondas' : quantity(data.config.rounds, 'ronda', 'rondas')} · ${data.config.duration} segundos por turno · ${data.config.modes.map(id => MODES[id].name).join(', ')}. Las respuestas solo aparecen en el móvil de quien juega.</p>
    <div class="lobby-actions">${data.identity.host ? button('start-room-game', `¡Estamos todos! ${icon('arrow')}`, 'primary', claimed !== data.teams.length ? 'disabled' : '') : button('leave-room', 'Cambiar de piña', 'secondary')}${data.identity.host ? button('room-tools', 'Gestionar sala', 'text') : ''}${button('disconnect-room', 'Salir de esta sala', 'text')}</div></section>`;
}

// ---- Game ----
export function gameView() {
  const game = S.game;
  if (!game) return '';
  if (isViewer()) return scoreboardView();
  const s = game.state;
  if (s.phase === 'finished') return finishedView();
  if (s.phase === 'summary') return summaryView();
  const active = isActive();
  const stage = s.phase === 'handoff' ? handoffView(active) : s.phase === 'paused' ? pausedView(active) : s.phase === 'exhausted' ? exhaustedView(active) : active ? cardView() : waitingView();
  const roundLabel = game.format === 'rounds3' ? `Ronda ${game.round} de 3` : s.config.target ? `Ronda ${game.round} · a ${s.config.target} pts` : `Ronda ${game.round} de ${s.config.rounds}`;
  return `<section class="game-shell"><div class="game-top"><span class="small-tag">${roundLabel}</span><span class="game-team">${pineapple(game.team, '', true)} ${escape(game.team.name)} <strong>${game.team.score} pts</strong></span>${S.remote && isHost() ? button('room-tools', icon('people'), 'icon-btn', 'aria-label="Gestionar sala y móviles"') : ''}${button('exit-game', icon('x'), 'icon-btn', 'aria-label="Salir de la partida"')}</div>${scoreStrip()}${stage}${S.remote && !S.connected ? `<div class="error-box" role="alert"><p>Conexión interrumpida. Estamos reconectando; los controles se activarán al recuperar la sala.</p>${isHost() ? button('continue-local', 'Seguir la partida en este móvil', 'text') : ''}</div>` : ''}</section>`;
}
function scoreStrip() {
  const s = S.game.state;
  return `<div class="game-score-strip">${s.teams.map(team => `<span class="${team.id === S.game.team.id ? 'current' : ''}"><i style="background:${team.color}"></i>${escape(team.name)}<b>${team.score}</b></span>`).join('')}</div>`;
}
const answerStyle = () => ({ large: ' style="font-size:1.3em"', huge: ' style="font-size:1.6em"' }[S.settings.answerSize] || '');
function handoffView(active) {
  const game = S.game, s = game.state;
  const fixed = game.turnMode ? MODES[game.turnMode] : null;
  const notes = [game.lightning && `${icon('timer')} ¡Ronda relámpago! Turnos de 30 segundos y puntos dobles.`, game.format === 'rounds3' && `${icon('shuffle')} Quedan ${s.deckCount ?? s.deck.length} de ${s.pileCount ?? s.pile?.length} tarjetas en esta ronda.`].filter(Boolean);
  return `<div class="handoff-card"><span class="eyebrow">LE TOCA A VUESTRA PIÑA</span>${pineapple(game.team, 'handoff-fruit')}<h1>${escape(game.team.name)}</h1><p class="handoff-instruction">${active ? game.player ? `<strong>${escape(game.player)}</strong>, hoy das las pistas.` : 'Elegid quién da las pistas.' : game.player ? `${escape(game.player)} da las pistas.` : 'Su piña está preparándose.'}</p><div class="private-note">${icon('phone')} ${active ? 'Pasa el móvil a quien da las pistas.' : 'Las respuestas aparecerán solo en el móvil de esta piña.'}</div>${fixed ? `<p class="round-mode">${icon(fixed.icon)} ${fixed.name}: ${fixed.rule}</p>` : '<p class="hint">Las modalidades se mezclan. Fíjate en la indicación de cada tarjeta.</p>'}${notes.map(note => `<p class="notice">${note}</p>`).join('')}${active ? button('ready', `Estoy listo ${icon('arrow')}`, 'primary large', canControl() ? '' : 'disabled') : '<div class="waiting-dots">Esperando a que estén listos<span>…</span></div>'}<small>La respuesta y el cronómetro empiezan al pulsar «Estoy listo».</small></div>`;
}
export function timerMarkup() { return `<div class="timer-block"><span class="timer-label">TIEMPO</span><strong id="time-left" role="timer" aria-label="Tiempo restante"></strong><div class="time-track"><i id="time-progress"></i></div></div>`; }
function gameControls() {
  const game = S.game, s = game.state;
  const skipText = s.config.skipPolicy === 'limited' ? `Saltar · ${Math.max(0, s.config.skipLimit - s.turn.skipped)}` : 'Saltar';
  const points = game.multiplier > 1 ? `+${game.multiplier}` : '+1';
  const canUndo = S.remote ? s.canUndo : game.canUndo;
  const controls = s.mode === 'taboo' ? button('forbidden', `${icon('lock')} <span class="control-label">¡Prohibida!${s.config.penalty ? ' −1' : ''}</span>`, 'secondary forbidden-control', canControl() ? '' : 'disabled') : '';
  return `<div class="game-controls ${s.mode === 'taboo' ? 'taboo-controls' : ''}">${button(s.allPlay ? 'award-picker' : 'correct', `${icon('check')} <span class="control-label">${s.allPlay ? '¿Quién la acertó?' : `Acertado ${points}`}</span>`, 'success', canControl() ? '' : 'disabled')}${button(s.config.steal ? 'steal-picker' : 'skipped', `${icon('skip')} <span class="control-label">${skipText}${s.config.penalty ? ' −1' : ''}</span>`, 'secondary', game.canSkip && canControl() ? '' : 'disabled')}${controls}${button('pause', `${icon('pause')} <span class="control-label">Pausar</span>`, 'secondary pause-control', 'aria-label="Pausar y ocultar respuesta"')}</div>
    <div class="turn-secondary-actions">${button('undo', `${icon('undo')} Deshacer la última`, 'secondary', canUndo && canControl() ? '' : 'disabled')}${button('report-card', `${icon('flag')} Reportar tarjeta`, 'secondary')}</div>`;
}
function cardView() {
  const game = S.game, s = game.state, m = MODES[s.mode] || MODES.description, card = s.current;
  if (!card) return waitingView();
  const forbidden = s.mode === 'taboo' && card.forbidden?.length ? `<div class="forbidden-words"><strong>Prohibido decir:</strong><ul>${card.forbidden.map(word => `<li>${escape(word)}</li>`).join('')}</ul></div>` : '';
  return `<div class="play-card ${m.color} ${s.mode === 'taboo' ? 'taboo-card' : ''} ${S.drawingOpen ? 'canvas-card' : ''}"><div class="play-card-top"><span class="mode-pill">${icon(m.icon)} ${m.name}</span><span class="turn-points">${s.turn.points > 0 ? '+' : ''}${quantity(s.turn.points, 'punto', 'puntos')} este turno</span></div>${s.allPlay ? `<p class="notice" role="status">${icon('people')} ¡Todos juegan! Cualquier piña puede acertarla.</p>` : ''}${timerMarkup()}
    ${S.drawingOpen ? `<div class="canvas-area"><div class="drawing-toolbar"><div class="ink-colors">${['#353348', '#e57f6d', '#599677', '#6389cb', '#e2af30'].map(color => `<button data-action="ink" data-value="${color}" class="ink-swatch ${pen.ink === color && !pen.eraser ? 'selected' : ''}" aria-pressed="${pen.ink === color && !pen.eraser}" style="--swatch:${color}" aria-label="Tinta ${color === '#353348' ? 'negra' : color === '#e57f6d' ? 'roja' : color === '#599677' ? 'verde' : color === '#6389cb' ? 'azul' : 'amarilla'}"></button>`).join('')}</div><label class="stroke-width" for="stroke-width">Trazo<input id="stroke-width" type="range" min="2" max="16" value="${pen.width}" data-input="stroke-width"/></label><div class="draw-tools">${button('eraser', icon('eraser'), `icon-btn ${pen.eraser ? 'selected' : ''}`, `aria-label="Goma" aria-pressed="${pen.eraser}"`)}${button('undo-stroke', icon('undo'), 'icon-btn', 'aria-label="Deshacer último trazo"')}${button('clear-canvas', icon('trash'), 'icon-btn', 'aria-label="Borrar todo el dibujo"')}</div></div><canvas id="draw-canvas" aria-label="Lienzo: dibuja aquí con el dedo o el ratón"></canvas><p class="hint">La respuesta está oculta. Ya puedes enseñar el dibujo a tu piña.</p></div>` : `<div class="answer-area"><span class="eyebrow">${escape(categoryName(card.category))}${card.subcategory ? ` · ${escape(card.subcategory)}` : ''}</span><h1 class="answer"${answerStyle()}>${escape(card.answer)}</h1><span class="difficulty-tag">${CARD_DIFFICULTIES[card.difficulty] || ''}</span><p class="card-rule">${s.mode === 'taboo' ? 'Da pistas sin decir la respuesta.' : m.rule}</p>${forbidden}${s.mode === 'drawing' && s.config.drawing === 'screen' ? button('open-canvas', `${icon('pencil')} Abrir lienzo y ocultar respuesta`, 'dark') : ''}</div>`}
    ${gameControls()}</div><p class="hint centered">${S.drawingOpen ? 'El tiempo sigue corriendo mientras dibujas.' : 'Solo quien da pistas debe mirar esta pantalla.'} · ${quantity(S.remote ? s.deckCount : s.deck.length, 'tarjeta restante', 'tarjetas restantes')}.</p>`;
}
function waitingView() {
  const s = S.game.state, m = MODES[s.mode];
  return `<div class="play-card waiting-card mint"><span class="mode-pill">${icon(m?.icon || 'people')} ${m?.name || 'En juego'}</span>${timerMarkup()}${s.allPlay ? `<p class="notice" role="status">${icon('people')} ¡Todos juegan! Vuestra piña también puede acertar esta tarjeta.</p>` : ''}<div class="waiting-content">${pineapple(S.game.team)}<h1>${escape(S.game.team.name)} está jugando</h1><p>Animad a vuestra piña. La respuesta se mantiene en privado.</p></div>${isHost() ? button('pause', `${icon('pause')} Pausar partida`, 'secondary') : ''}</div>`;
}
function pausedView(active) { return `<div class="privacy-card"><span class="privacy-symbol">${icon('pause')}</span><span class="eyebrow">UN RESPIRO PARA LA PIÑA</span><h1>Partida en pausa</h1><p>La respuesta está oculta y el tiempo detenido.</p><strong class="paused-time">${Math.ceil(S.game.state.remaining / 1000)} s restantes</strong>${active ? button('resume', `${icon('play')} Continuar turno`, 'primary large', canControl() ? '' : 'disabled') : '<p class="hint">El móvil de la piña que juega reanudará el turno.</p>'}${isHost() ? `${button('adjust-score', 'Corregir el marcador', 'text')}${button('finish-confirm', 'Terminar y ver resultados', 'text')}` : ''}</div>`; }
function exhaustedView(active) { return `<div class="privacy-card">${pineapple({ color: COLORS[3], accessories: ['glasses'] }, 'small-fruit')}<span class="eyebrow">¡OS LAS SABÉIS TODAS!</span><h1>No quedan tarjetas</h1><p>El reloj se ha detenido. Podéis volver a mezclar las respuestas utilizadas o terminar aquí.</p>${active ? `<div class="stack-actions">${button('reuse', `${icon('shuffle')} Reutilizar tarjetas`, 'primary', canControl() ? '' : 'disabled')}${button('undo', `${icon('undo')} Deshacer la última`, 'text', canControl() ? '' : 'disabled')}${button('finish', 'Terminar partida', 'secondary')}</div>` : isHost() ? button('finish', 'Terminar partida', 'secondary') : '<p class="hint">La piña que juega decide si seguimos.</p>'}<small>Solo se repetirán respuestas si elegís reutilizarlas.</small></div>`; }
export function rankingView() {
  let position = 0, previous;
  return `<ol class="ranking">${S.game.ranking.map((team, i) => { if (team.score !== previous) position = i + 1; previous = team.score; return `<li><span class="ranking-position">${position === 1 ? icon('crown') : String(position).padStart(2, '0')}</span>${pineapple(team, '', true)}<div><strong>${escape(team.name)}</strong><small>${team.members.map(escape).join(', ') || 'Una gran piña'}</small></div><b>${team.score}<small>${team.score === 1 ? 'punto' : 'puntos'}</small></b></li>`; }).join('')}</ol>`;
}
const RESULT_LABELS = { correct: 'Acertada', skipped: 'Saltada', forbidden: 'Prohibida', awarded: 'Para otra piña', pending: 'Sin resolver' };
function summaryView() {
  const game = S.game, s = game.state;
  const canRevise = (isActive() || isHost()) && game.format === 'classic' && !isViewer();
  const teamName = id => s.teams.find(team => team.id === id)?.name || '';
  const stageNote = game.format === 'rounds3' ? s.stageComplete ? `<p class="notice">${icon('check')} ¡Ronda ${game.round} completada! ${game.round < 3 ? `La siguiente es de ${MODES[['description', 'oneword', 'mime'][game.round]].name.toLowerCase()} con las mismas tarjetas.` : ''}</p>` : `<p class="hint">Quedan ${s.deckCount ?? s.deck.length} tarjetas en esta ronda.</p>` : '';
  return `<section class="summary-shell">${title(`RONDA ${game.round} · ${escape(game.team.name).toUpperCase()}`, '¡Buen turno, piña!', S.remote ? 'Así queda la cosa. Preparad el siguiente móvil y a por más.' : 'Así queda la cosa. Pasad el móvil a la siguiente piña y a por más.')}
    <div class="turn-stats"><div><strong>${s.turn.correct}</strong><span>Aciertos</span></div><div><strong>${s.turn.skipped}</strong><span>Saltos</span></div><div><strong>${s.turn.points > 0 ? '+' : ''}${s.turn.points}</strong><span>Puntos del turno</span></div></div>${stageNote}
    <div class="summary-grid"><div><h2>La clasificación</h2>${rankingView()}${adjustmentsList()}</div><div class="turn-log panel"><h2>Vuestras tarjetas</h2>${s.turn.log.length ? s.turn.log.map((entry, i) => `<div><span>${escape(entry.answer)}${entry.result === 'awarded' ? `<small>${escape(teamName(entry.teamId))}</small>` : ''}</span>${canRevise ? `<button class="text-link result-${entry.result === 'forbidden' ? 'skipped' : entry.result === 'awarded' ? 'correct' : entry.result}" data-action="revise" data-value="${i}" aria-label="${RESULT_LABELS[entry.result]}: cambiar el resultado de ${escape(entry.answer)}">${RESULT_LABELS[entry.result]} ${icon('shuffle')}</button>` : `<small class="result-${entry.result === 'forbidden' ? 'skipped' : entry.result === 'awarded' ? 'correct' : entry.result}">${RESULT_LABELS[entry.result]}</small>`}</div>`).join('') : '<p class="hint">No se mostraron tarjetas en este turno.</p>'}<p class="hint">${canRevise ? '¿Algún error? Toca el resultado para corregirlo antes de pasar el turno.' : 'Todas estas tarjetas se consideran utilizadas.'}</p></div></div>
    <div class="centered">${isActive() || isHost() ? button('next', `${game.lastTurn ? 'Ver resultado final' : 'Siguiente piña'} ${icon('arrow')}`, 'primary large') : '<p class="hint">El maestro o la piña que acaba de jugar darán paso al siguiente turno.</p>'}${isHost() ? button('adjust-score', 'Corregir el marcador', 'text') : ''}${S.remote && isHost() ? button('room-tools', 'Gestionar sala', 'text') : ''}${button('exit-game', 'Salir de la partida', 'text')}</div></section>`;
}
function adjustmentsList() {
  const s = S.game.state;
  if (!s.adjustments?.length) return '';
  const name = id => s.teams.find(team => team.id === id)?.name || '';
  return `<p class="hint">Ajustes manuales: ${s.adjustments.map(item => `${escape(name(item.teamId))} ${item.delta > 0 ? '+' : ''}${item.delta}`).join(' · ')}</p>`;
}
function finishedView() {
  const game = S.game, winners = game.winners, stats = gameStats(game.state);
  const facts = stats ? [stats.bestTurn && `<div><strong>+${stats.bestTurn.points}</strong><span>Mejor turno: ${escape(stats.bestTurn.team)}${stats.bestTurn.player ? ` (${escape(stats.bestTurn.player)})` : ''}</span></div>`, stats.topPlayer && `<div><strong>${stats.topPlayer.correct}</strong><span>Más aciertos dando pistas: ${escape(stats.topPlayer.name)}</span></div>`, stats.fastest && `<div><strong>${seconds(stats.fastest.ms)}</strong><span>Acierto más rápido: ${escape(stats.fastest.team)}</span></div>`, `<div><strong>${stats.correct}</strong><span>Tarjetas acertadas en ${quantity(stats.turns, 'turno', 'turnos')}</span></div>`].filter(Boolean) : [];
  return `<section class="finished-shell"><span class="eyebrow">UNA PARTIDA PARA RECORDAR</span><div class="winner-fruits">${winners.map(team => pineapple(team)).join('')}<span class="winner-spark" aria-hidden="true">✳</span></div><span class="winner-label">${icon('trophy')} ${winners.length > 1 ? '¡Tenemos empate!' : '¡La piña ganadora!'}</span><h1>${winners.map(team => escape(team.name)).join(' y ')}</h1><p>${quantity(winners[0].score, 'punto', 'puntos')} y un montón de buenos momentos.</p>${facts.length ? `<div class="turn-stats">${facts.join('')}</div>` : ''}<div class="final-ranking">${rankingView()}</div><div class="finished-actions">${isHost() ? button('rematch', `${icon('shuffle')} ¡Revancha!`, 'primary large') : '<p class="hint">El maestro puede empezar la revancha.</p>'}${button('share-result', `${icon('share')} Compartir resultado`, 'secondary large')}${button('another-game', 'Crear otra partida', 'secondary large')}${S.remote && isHost() ? button('room-tools', 'Gestionar sala', 'text') : ''}</div><small>La revancha conserva equipos y reglas. Puntos y tarjetas empiezan de cero, y no se repiten las tarjetas de esta partida.</small></section>`;
}
// Read-only scoreboard for a TV, tablet or computer: who plays, time and points. Never shows an answer.
function scoreboardView() {
  const game = S.game, s = game.state, m = MODES[s.mode];
  const phase = { handoff: `Le toca a ${escape(game.team.name)}`, playing: `${escape(game.team.name)} está jugando`, paused: 'Partida en pausa', exhausted: 'No quedan tarjetas', summary: `Fin del turno de ${escape(game.team.name)}`, finished: `${game.winners.length > 1 ? '¡Empate!' : `¡Gana ${escape(game.winners[0].name)}!`}` }[s.phase];
  return `<section class="finished-shell"><span class="eyebrow">MARCADOR · SALA ${S.remote.code}</span>${pineapple(game.team, 'handoff-fruit')}<h1>${phase}</h1>${s.phase === 'playing' ? `${m ? `<p class="round-mode">${icon(m.icon)} ${m.name}</p>` : ''}${timerMarkup()}${s.allPlay ? `<p class="notice">${icon('people')} ¡Todos juegan!</p>` : ''}` : ''}<div class="final-ranking">${rankingView()}</div><small>${game.format === 'rounds3' ? `Ronda ${game.round} de 3` : `Ronda ${game.round}`} · Las respuestas solo aparecen en el móvil de quien juega.</small></section>`;
}
